    ('Flaking paint with exposed primer', 'Find paint that is peeling away in chips or flakes to reveal the lighter colored primer layer underneath the topcoat.', 'Show door paint flaking away to reveal undercoat or primer layer visible on the exposed areas.', 'uncommon'::public.item_rarity, 'Primer adhesion failure exposes it because primers are engineered to bond to bare substrate better than to previous paint coats.', 'https://cejsntpvctcgezrluvql.supabase.co/storage/v1/object/public/collection-item-images/00000000-0000-0000-0000-000000000001/wiki-cache/395bee9672edc8ec.jpg', 12),
    ('Water-damaged door edge', 'Look for the bottom or side edges of the door where water damage has swollen, softened, or darkened the wood, sometimes with mold.', 'Capture a door edge showing water damage signs: swelling, discoloration, warping, or darkened wood stains.', 'uncommon'::public.item_rarity, 'Wood swelling from water absorption is permanent at microscopic level; cell walls don''t fully return to original dimensions after drying.', 'https://cejsntpvctcgezrluvql.supabase.co/storage/v1/object/public/collection-item-images/00000000-0000-0000-0000-000000000001/wiki-cache/dcea91e7a08a27ad.jpg', 13),
